SELECT pro.id, pro.code, pro.purchase_order_code AS purchaseOrderCode, pro.supplier_name AS supplierName, pro.approve_status AS approveStatus, pro.invalid_status AS invalidStatus, prod.sku_id AS skuId, prod.sku_no AS skuNo, pro.bill_date AS billDate, pro.return_warehouse_id AS returnWarehouseId, pro.return_warehouse_name AS returnWarehouseName, prod.return_qty AS returnQty, prod.return_price AS returnPrice, prod.deduct_amount_qty AS deductAmountQty, prod.currency, prod.currency_symbol AS currencySymbol, pro.return_remark AS returnRemark, pro.return_mode AS returnMode, pro.purchase_user_id AS purchaseUserId, pro.return_user_name AS returnUserName, prod.remark, pro.approve_user_name AS approveUserName, pro.create_user_name AS createUserName, pro.create_time AS createTime, prod.remark, prod.warehouse_location AS warehouseLocation, pro.source_type AS sourceType, prod.purchase_order_detail_id AS purchaseOrderDetailId, pro.unusual_type, pro.unusual_remark, pro.unusual_handle_user_id, pro.unusual_handle_user_name, pro.confirm_date FROM po_return_detail prod INNER JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE pro.is_deleted = FALSE
and pro.code = #{params.code}
and prod.sku_no in
#{item}
and pro.supplier_id in
#{item}
and pro.purchase_order_code = #{params.purchaseOrderCode}
and pro.purchase_user_id in
#{item}
and pro.approve_status in
#{item}
and pro.invalid_status = #{params.invalidStatus}
and pro.return_mode = #{params.returnMode}
and prod.remark ilike concat('%',#{params.detailRemark}::text,'%')
and pro.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pro.bill_date
and pro.return_warehouse_id in
#{item}
and pro.create_user_id in
#{item}
and pro.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pro.create_time
and pro.source_type != 'qcInfo'
and pro.source_type = 'qcInfo'
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pro.create_time desc,pro.id

SELECT pro.approve_status, prod.sku_id, prod.sku_no, pro.purchase_order_id, SUM(wrd.return_qty) AS returnQty FROM po_return_detail prod LEFT JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE pro.is_deleted = FALSE
AND wr.purchase_order_id = #{purchaseOrderId}
GROUP BY pro.approve_status, prod.sku_id, prod.sku_no, pro.purchase_order_id

