SELECT DISTINCT pro.id, pro.code, pro.approve_status, pro.supplier_name, pro.return_warehouse_name, pro.create_time FROM po_return_detail prod INNER JOIN po_return pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE pro.is_deleted = FALSE AND pro.invalid_status = FALSE
and pro.approve_status in
#{item}
AND pro.bill_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pro.bill_date
